<template>
  <MessageBanner
    v-if="accessDenied"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <q-page
    v-else-if="accessGranted"
    class="touchless-document-trace"
    data-test="touchless-document-trace-page"
  >
    <SubHeader
      name="touchless_document_trace"
      :label="$t('touchless_document_trace')"
      :show_expiry_alert="true"
      :onSearch="false"
      :display_back_button="true"
      :back_to_link="TOUCHLESS_TAB_PATH"
    />

    <div class="q-pa-md">
      <!-- Document header -->
      <div class="row items-center q-mb-md">
        <div>
          <div class="doc-id" data-test="touchless-trace-doc-id">
            {{ docId }}
          </div>
          <div class="row items-center q-gutter-xs q-mt-xs">
            <q-chip
              dense
              square
              color="primary"
              text-color="white"
              :label="bucketLabel"
              data-test="touchless-trace-bucket"
            />
            <q-chip
              dense
              square
              :color="outcome?.human_touched ? 'warning' : 'positive'"
              text-color="white"
              :label="
                outcome?.human_touched
                  ? $t('touchless_human_touched')
                  : $t('touchless_no_human_touch')
              "
              data-test="touchless-trace-human-touched"
            />
            <q-chip
              v-if="outcome?.first_blocking_stage"
              dense
              square
              outline
              :label="
                $t('touchless_first_blocker') + ': ' + firstBlockingStageLabel
              "
              data-test="touchless-trace-first-blocker"
            />
          </div>
        </div>
        <q-space />
        <q-btn
          v-if="documentRoute"
          flat
          dense
          no-caps
          icon="open_in_new"
          :label="$t('touchless_open_document')"
          :to="documentRoute"
          data-test="touchless-trace-open-document"
        />
      </div>

      <div
        v-if="loadError"
        class="text-center q-pa-xl"
        data-test="touchless-trace-error"
      >
        <q-icon name="cloud_off" size="56px" color="grey-5" />
        <p class="q-mt-sm text-grey-6">{{ $t('failed_to_load') }}</p>
        <q-btn
          flat
          :label="$t('retry')"
          icon="refresh"
          size="sm"
          @click="load"
        />
      </div>

      <div v-else-if="loading" class="q-pa-md">
        <q-skeleton type="text" width="60%" class="q-mb-sm" />
        <q-skeleton type="rect" height="180px" />
      </div>

      <div
        v-else-if="!runs.length"
        class="text-center q-pa-xl"
        data-test="touchless-trace-empty"
      >
        <q-icon name="history" size="48px" color="grey-5" />
        <p class="q-mt-sm text-grey-6">{{ $t('touchless_no_trace_runs') }}</p>
      </div>

      <template v-else>
        <!--
          DOCB-14351. The WAY through the pipeline, above the per-run detail:
          a reader asks "where did it stop" before "what happened in run 2",
          and the runs below answer the second question.
        -->
        <TouchlessWidgetWrapper
          v-if="pipeline"
          :title="$t('pipeline_flow_title')"
          icon="mdi:transit-connection-variant"
          class="q-mb-md"
          data-test="touchless-trace-pipeline"
        >
          <!--
            The `po_line_match` node is a drill-down into the PO-match panel
            below (DOCB-14348) — but only when that panel is actually on the
            page. Offering a click that scrolls to nothing is worse than not
            offering it, so the two conditions are the same one.
          -->
          <PipelineFlow
            mode="document"
            :stages="pipeline.stages"
            :po-match-drilldown="showsPoMatch"
            data-test="touchless-trace-pipeline-flow"
            @drilldown="focusPoMatch"
          />
          <PipelineWhyBlocked
            class="q-mt-md"
            :explanation="pipeline.explanation"
            :blocking-stage="pipelineBlockingStage"
          />
        </TouchlessWidgetWrapper>

        <TouchlessWidgetWrapper
          v-for="run in runs"
          :key="run.run_seq"
          :title="runTitle(run)"
          icon="mdi:history"
          class="q-mb-md"
          :data-test="`touchless-trace-run-${run.run_seq}`"
        >
          <template #header-actions>
            <q-chip
              dense
              square
              outline
              :label="translateEnum('touchless_run_outcome_', run.outcome)"
              :data-test="`touchless-trace-run-outcome-${run.run_seq}`"
            />
          </template>

          <q-timeline class="q-pa-md" color="primary">
            <q-timeline-entry
              v-for="(stage, index) in run.stages"
              :key="`${stage.stage}-${stage.attempt}-${index}`"
              :title="stageTitle(stage)"
              :subtitle="stageSubtitle(stage)"
              :color="stageColor(stage.status)"
              :icon="stageIcon(stage.status)"
              :data-test="`touchless-trace-stage-${stage.stage}`"
              :class="`touchless-stage touchless-stage--${String(stage.status).toLowerCase()}`"
            >
              <div
                v-if="stage.reason_code"
                class="stage-reason"
                :data-test="`touchless-trace-reason-${stage.stage}`"
              >
                {{ translateEnum('touchless_reason_', stage.reason_code) }}
              </div>
              <div v-if="stageDetail(stage)" class="stage-detail">
                {{ stageDetail(stage) }}
              </div>
            </q-timeline-entry>
          </q-timeline>

          <!--
            The stickiness rule, said where it surprises people: a run that
            went through cleanly does NOT give the document its touchless
            status back. Without this note the trace shows a green run above a
            document counted as touched, and the only way to learn why is to
            ask someone.
          -->
          <div
            v-if="showsStickyNote(run)"
            class="sticky-note"
            :data-test="`touchless-trace-sticky-${run.run_seq}`"
          >
            <q-icon name="info_outline" size="16px" />
            <span>{{ $t('touchless_trace_sticky_note') }}</span>
          </div>
        </TouchlessWidgetWrapper>

        <!--
          Why PO matching did or did not go through, for this document
          (DOCB-14348). Shown only when PO matching is actually part of this
          document's story: on a document that never reached the matcher the
          panel would explain a step that did not run.

          The `po_line_match` node of the pipeline diagram above scrolls here
          (DOCB-14351's `@drilldown`), which is why this section carries a ref:
          the reader clicked the stage that stopped their document and expects
          to land on the reason, not to hunt for it down the page.
        -->
        <div ref="poMatchSection">
          <PoMatchExplanationPanel
            v-if="showsPoMatch"
            class="q-mt-md"
            mode="document"
            :doc-id="normalizedDocId || ''"
            data-test="touchless-trace-po-match"
          />
        </div>

        <MetricContractFooter :data-as-of="trace?.data_as_of || ''" />
      </template>
    </div>
  </q-page>
  <!-- Preferences still loading: neither grant nor deny is known yet. -->
  <q-page
    v-else
    class="touchless-document-trace q-pa-md"
    data-test="touchless-gate-pending"
  >
    <q-skeleton type="text" width="30%" class="q-mb-md" />
    <q-skeleton type="rect" height="120px" />
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { RouteLocationRaw } from 'vue-router';
import MessageBanner from 'src/components/MessageBanner.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { pipelineExplanationService, touchlessService } from 'src/services';
import type {
  TouchlessDocumentTraceResponse,
  TouchlessTraceOutcome,
  TouchlessTraceRun,
  TouchlessTraceStage,
} from 'src/services/analytics/TouchlessService';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import {
  isValidTraceResponse,
  normalizeDocumentId,
} from 'src/utils/touchless-guards';
import type {
  PipelineExplanationResponse,
  PipelineStage,
} from 'src/services/analytics/PipelineExplanationService';
import { isValidPipelineResponse } from 'src/services/analytics/PipelineExplanationService';
import {
  DOCUMENT_VIEW_ROUTE,
  TOUCHLESS_TAB_PATH,
} from 'src/router/touchless-routes';
import TouchlessWidgetWrapper from './components/TouchlessWidgetWrapper.vue';
import PipelineFlow from './components/PipelineFlow.vue';
import PipelineWhyBlocked from './components/PipelineWhyBlocked.vue';
import { showsRestartStickyNote } from 'src/utils/touchless-format';
import MetricContractFooter from './components/MetricContractFooter.vue';
import PoMatchExplanationPanel from './components/PoMatchExplanationPanel.vue';

/**
 * The pipeline stages that mean the PO matcher was involved. Named here
 * rather than inlined so the condition reads as what it is: "did this
 * document ever get as far as a purchase order".
 */
const PO_MATCH_STAGES = ['po_lookup', 'po_line_match'];

/**
 * Stage-by-stage trace of one document across every run it went through.
 *
 * A restart creates a NEW run rather than overwriting the old one, so the
 * timeline shows why automation stopped the first time even when a later,
 * human-triggered run finished cleanly. Rendering only the last run would hide
 * exactly the fact this page exists to show.
 *
 * Timeline pattern: src/components/Approval/ApprovalHistory.vue.
 */
export default defineComponent({
  name: 'TouchlessDocumentTrace',

  components: {
    MessageBanner,
    SubHeader,
    TouchlessWidgetWrapper,
    MetricContractFooter,
    PipelineFlow,
    PipelineWhyBlocked,
    PoMatchExplanationPanel,
  },

  setup() {
    const { accessGranted, accessDenied, checkAccess, ensureSettingsLoaded } =
      useTouchlessAccess();
    return { accessGranted, accessDenied, checkAccess, ensureSettingsLoaded };
  },

  data() {
    return {
      // Back goes to the analytics page WITH the Touchless tab selected —
      // without the query the reader lands on Status, which is not where they
      // came from.
      TOUCHLESS_TAB_PATH,
      loading: false,
      loadError: false,
      // Ownership token: only the newest load may commit. See load().
      loadGeneration: 0,
      trace: null as TouchlessDocumentTraceResponse | null,
      // DOCB-14351. Loaded ALONGSIDE the trace, never instead of it: the
      // timeline is this page's contract and a pipeline read that fails must
      // leave it standing.
      pipeline: null as PipelineExplanationResponse | null,
    };
  },

  computed: {
    /** The raw route param, shown verbatim in the header. */
    docId(): string {
      return String(this.$route.params.docId || '');
    },

    /**
     * The canonical form of the route param, or null. Everything that leaves
     * the component — the request and the deep link — uses THIS, so a padded
     * value cannot validate here and 404 there.
     */
    normalizedDocId(): string | null {
      return normalizeDocumentId(this.docId);
    },

    /**
     * Built only from an id that already passed UUID validation. A link
     * assembled from whatever sat in the URL would navigate to a guaranteed
     * 404 — and the same unvalidated value is refused a request in load().
     * Null means: render no button at all.
     */
    documentRoute(): RouteLocationRaw | null {
      const docId = this.normalizedDocId;
      if (!docId) return null;
      return { name: DOCUMENT_VIEW_ROUTE, params: { id: docId } };
    },

    runs(): TouchlessTraceRun[] {
      return this.trace?.runs || [];
    },

    /**
     * The stage the document stopped at, as the API named it.
     *
     * Looked up in `stages` by the key `first_blocker` reports rather than
     * re-derived here: the backend already walked STAGE_ORDER to pick it, and
     * a second walk on this side is a second answer waiting to disagree.
     */
    pipelineBlockingStage(): PipelineStage | null {
      const key = this.pipeline?.first_blocker?.stage;
      if (!key) return null;
      return (
        (this.pipeline?.stages || []).find((stage) => stage.key === key) || null
      );
    },

    /**
     * Whether PO matching is part of THIS document's story (DOCB-14348).
     *
     * Gated on a recorded PO stage rather than shown unconditionally: on a
     * document that never reached the matcher — a credit note, a document
     * that failed classification — the panel would explain a step that did
     * not run, and an explanation of a step that did not run is noise dressed
     * as insight.
     */
    showsPoMatch(): boolean {
      if (!this.normalizedDocId) return false;
      return this.runs.some((run) =>
        (run.stages || []).some((stage) =>
          PO_MATCH_STAGES.includes(String(stage.stage)),
        ),
      );
    },

    /**
     * The document-level facts, as the API sends them: under `outcome`, next
     * to `runs`. The header used to read `kpi_bucket` and `human_touched` off
     * the response root, where they have never been.
     */
    outcome(): TouchlessTraceOutcome | null {
      return this.trace?.outcome || null;
    },

    bucketLabel(): string {
      return this.translateEnum(
        'touchless_bucket_',
        this.outcome?.kpi_bucket || '',
      );
    },

    firstBlockingStageLabel(): string {
      return this.translateEnum(
        'touchless_stage_',
        this.outcome?.first_blocking_stage || '',
      );
    },
  },

  watch: {
    // Reactive gate: on a cold load the preferences arrive after mount, so the
    // trace loads the moment access is granted rather than staying blank.
    accessGranted: {
      immediate: true,
      handler(granted: boolean) {
        if (granted) void this.load();
      },
    },

    '$route.params.docId'(next: string, previous: string) {
      if (next && next !== previous) {
        void this.load();
      }
    },
  },

  async mounted() {
    await this.ensureSettingsLoaded();
  },

  methods: {
    /**
     * Bring the PO-match explanation into view (DOCB-14348).
     *
     * The pipeline diagram's `po_line_match` node is a link to this section.
     * `scrollIntoView` rather than a router hash: the section is already
     * mounted, and a hash would add a history entry for a scroll the reader
     * did not ask to be able to go back from.
     */
    focusPoMatch(): void {
      const section = this.$refs.poMatchSection as HTMLElement | undefined;
      if (!section || typeof section.scrollIntoView !== 'function') return;
      section.scrollIntoView({ behavior: 'smooth', block: 'start' });
    },

    async load(): Promise<void> {
      // The router REUSES this component across document ids, so two loads can
      // be in flight at once. Without an ownership token, document A resolving
      // after B renders A's timeline under B's id, and A's `finally` clears B's
      // loading flag.
      //
      // Claimed FIRST, before the guards below: a refused load still has to
      // invalidate whatever was in flight. Incrementing after the id check let
      // a pending request for document A stay "current" when the route moved to
      // an invalid id — and A then committed under the new route.
      const generation = ++this.loadGeneration;
      const isCurrent = () => generation === this.loadGeneration;

      // Defense in depth: the route-param watcher can re-enter here after the
      // flag was revoked mid-session. Evaluated fresh, not from the cached
      // computed the template renders from.
      if (!this.checkAccess()) return;

      // An id that cannot be a documents.id is not worth a request.
      const docId = this.normalizedDocId;
      if (!docId) {
        this.loadError = true;
        this.trace = null;
        this.loading = false;
        return;
      }

      this.loading = true;
      this.loadError = false;
      try {
        const result = await touchlessService.getDocumentTrace(docId);
        if (!isCurrent()) return;
        // A resolved auth-error payload would otherwise render as a document
        // with no runs, which reads as "nothing ever happened to it".
        if (!isValidTraceResponse(result)) {
          throw new Error('Malformed touchless trace response');
        }
        this.trace = result;
        await this.loadPipeline(docId, isCurrent);
      } catch {
        if (!isCurrent()) return;
        this.loadError = true;
        this.trace = null;
      } finally {
        if (isCurrent()) this.loading = false;
      }
    },

    /**
     * The pipeline path, loaded after the trace and never allowed to break it.
     *
     * Its own try/catch on purpose: this page existed before the pipeline
     * routes did, and a 404 or a slow answer from them must cost the reader
     * the diagram, not the timeline they came for. `isCurrent` is the SAME
     * ownership token the trace load uses, so a stale pipeline cannot land
     * under a newer document either.
     */
    async loadPipeline(docId: string, isCurrent: () => boolean): Promise<void> {
      try {
        const result =
          await pipelineExplanationService.getDocumentPipeline(docId);
        if (!isCurrent()) return;
        this.pipeline = isValidPipelineResponse(result) ? result : null;
      } catch {
        if (isCurrent()) this.pipeline = null;
      }
    },

    /** i18n label for an enum value, falling back to the raw backend value. */
    translateEnum(prefix: string, value: string): string {
      if (!value) return '';
      const key = `${prefix}${String(value).toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? value : translated;
    },

    /** Delegates to the shared rule; see `showsRestartStickyNote`. */
    showsStickyNote(run: TouchlessTraceRun): boolean {
      return showsRestartStickyNote(this.outcome?.human_touched, run);
    },

    runTitle(run: TouchlessTraceRun): string {
      const trigger = this.translateEnum(
        'touchless_trigger_',
        run.trigger || '',
      );
      return this.$t('touchless_run_title', {
        seq: run.run_seq,
        trigger,
      }) as string;
    },

    stageTitle(stage: TouchlessTraceStage): string {
      return this.translateEnum('touchless_stage_', stage.stage);
    },

    stageSubtitle(stage: TouchlessTraceStage): string {
      const status = this.translateEnum(
        'touchless_stage_status_',
        String(stage.status),
      );
      if (stage.attempt && stage.attempt > 1) {
        return `${status} · ${this.$t('touchless_attempt', { attempt: stage.attempt })}`;
      }
      return status;
    },

    /**
     * Detail JSON is capped at 4KB by the backend; render it as a compact line.
     * Detail KEYS come from the backend registry and may grow, so a known key is
     * translated and an unknown one renders raw rather than vanishing behind a
     * missing-key placeholder. Values are backend data and are never translated.
     */
    stageDetailKeyLabel(key: string): string {
      const i18nKey = `touchless_detail_${String(key).toLowerCase()}`;
      const translated = this.$t(i18nKey) as string;
      return translated === i18nKey ? key : translated;
    },

    stageDetail(stage: TouchlessTraceStage): string {
      if (!stage.detail || typeof stage.detail !== 'object') return '';
      const entries = Object.keys(stage.detail);
      if (!entries.length) return '';
      return entries
        .map(
          (key) =>
            `${this.stageDetailKeyLabel(key)}: ${String(
              (stage.detail as Record<string, unknown>)[key],
            )}`,
        )
        .join(' · ');
    },

    stageColor(status: string): string {
      switch (String(status).toLowerCase()) {
        case 'passed':
          return 'positive';
        case 'blocked':
          return 'warning';
        case 'failed':
          return 'negative';
        case 'skipped':
        case 'not_applicable':
          return 'grey-5';
        default:
          return 'grey-7';
      }
    },

    stageIcon(status: string): string {
      switch (String(status).toLowerCase()) {
        case 'passed':
          return 'check';
        case 'blocked':
          return 'pause';
        case 'failed':
          return 'close';
        case 'skipped':
        case 'not_applicable':
          return 'remove';
        default:
          return 'help_outline';
      }
    },
  },
});
</script>

